<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>Calculator</title>
<style>
  :root {
    --bg: #0f1220;
    --panel: rgba(255, 255, 255, 0.06);
    --panel-border: rgba(255, 255, 255, 0.12);
    --text: #f2f4ff;
    --muted: #8b93b5;
    --accent: #6c8cff;
    --accent-2: #a06bff;
    --op: #2a3050;
    --op-hover: #353d66;
    --danger: #ff6b81;
    --radius: 18px;
  }

  * { box-sizing: border-box; }

  html, body {
    height: 100%;
    margin: 0;
  }

  body {
    display: grid;
    place-items: center;
    padding: 20px;
    font-family: "Inter", "Segoe UI", system-ui, -apple-system, sans-serif;
    color: var(--text);
    background:
      radial-gradient(900px 600px at 15% 10%, #1d2450 0%, transparent 60%),
      radial-gradient(800px 600px at 85% 90%, #3a1d4f 0%, transparent 60%),
      var(--bg);
    -webkit-font-smoothing: antialiased;
  }

  .calculator {
    width: min(100%, 380px);
    padding: 22px;
    border-radius: 28px;
    background: var(--panel);
    border: 1px solid var(--panel-border);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    box-shadow:
      0 30px 60px -20px rgba(0, 0, 0, 0.75),
      inset 0 1px 0 rgba(255, 255, 255, 0.08);
  }

  /* ---------- Display ---------- */
  .display {
    padding: 18px 16px 14px;
    margin-bottom: 18px;
    border-radius: var(--radius);
    background: rgba(0, 0, 0, 0.28);
    border: 1px solid rgba(255, 255, 255, 0.06);
    text-align: right;
    overflow: hidden;
  }

  .history {
    min-height: 22px;
    font-size: 0.95rem;
    color: var(--muted);
    letter-spacing: 0.02em;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    transition: color 0.2s ease;
  }

  .output {
    font-size: clamp(2rem, 9vw, 2.9rem);
    font-weight: 600;
    line-height: 1.15;
    letter-spacing: -0.02em;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    font-variant-numeric: tabular-nums;
  }

  .output.error {
    color: var(--danger);
    font-size: clamp(1.4rem, 6vw, 1.9rem);
  }

  /* ---------- Keypad ---------- */
  .keys {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
  }

  button {
    -webkit-tap-highlight-color: transparent;
    appearance: none;
    border: 1px solid rgba(255, 255, 255, 0.07);
    border-radius: var(--radius);
    padding: 0;
    height: clamp(56px, 15vw, 68px);
    font-family: inherit;
    font-size: clamp(1.05rem, 4.2vw, 1.3rem);
    font-weight: 500;
    color: var(--text);
    background: rgba(255, 255, 255, 0.07);
    cursor: pointer;
    transition: transform 0.08s ease, background 0.18s ease, box-shadow 0.18s ease;
    user-select: none;
  }

  button:hover { background: rgba(255, 255, 255, 0.13); }

  button:active {
    transform: scale(0.95);
    background: rgba(255, 255, 255, 0.2);
  }

  button:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
  }

  .op {
    background: var(--op);
    color: #cfd8ff;
    font-weight: 600;
  }
  .op:hover { background: var(--op-hover); }

  .func {
    background: rgba(255, 255, 255, 0.04);
    color: var(--muted);
    font-size: clamp(0.95rem, 3.6vw, 1.1rem);
  }

